// Authored intermediate-course source. Run with `node tools/author-course-intermediate.mjs`.
// The helpers only expand the individually written teaching, task and application text.
import fs from 'node:fs';

const read = (path) => JSON.parse(fs.readFileSync(path, 'utf8'));
const old = {B1: read('data/grammar-course/B1.json'), B2: read('data/grammar-course/B2.json')};
const representative = read('data/course-v2/B1.json').units[0].lessons[0];
representative.legacyLessonIds=['b1-background-event'];
representative.steps=representative.steps.filter(s=>!s.reserve);
const allOld = Object.fromEntries(Object.values(old).flatMap(p => p.units.flatMap(u => u.lessons)).map(l => [l.id,l]));
const lessons = {B1: {}, B2: {}};
const targetId = id => `${id}.core`;
const phraseWords = (items) => items.map(item => {
  const [it,en,entryId] = item;
  return {...{it,en}, ...(entryId ? {entryId} : {})};
});
const step = (id, suffix, kind, extra) => ({id: `${id}.${suffix}`, kind, ...extra});
function separatedChecks(id,checks){
  const result=[];
  checks.forEach((q,i)=>{
    result.push(q);
    if(i<checks.length-1){
      result.push(step(id,`contrast-${i+1}`,'teach',{title:'Notice why it fits',body:q.explanation,examples:[{it:q.speak||q.answer,en:q.translation||'Review the Italian wording in context.'}]}));
    }
  });
  return result;
}
function target(id,label,body,example,facets=['use']) {
  return {id:targetId(id),label,explanation:body,facets,minIndependent:3,requiresProduction:true,modality:'language',repair:{title:`Try ${label.toLowerCase()} again`,body,examples:[example]}};
}
function lessonBase(id,title,outcome,prerequisites,takeaway,related,targets,steps,legacyLessonIds=[]) {
  return {id,title,outcome,minutes:7,prerequisites,related,takeaway,targets,steps,...(legacyLessonIds.length?{legacyLessonIds}:{})};
}
function register(level,lesson) {
  if (lessons[level][lesson.id]) throw Error(`duplicate ${lesson.id}`);
  lessons[level][lesson.id]=lesson;
  return lesson;
}
function addReserve(level,suffix,context,translation,answer,distractors,facet){
  const id=`v2-${level.toLowerCase()}-${suffix}`, l=lessons[level][id];
  if(!l) throw Error(`reserve missing ${id}`);
  const n=l.steps.filter(s=>s.reserve).length+1;
  const productive=Boolean(l.legacyLessonIds?.length);
  const q=step(id,`reserve-${n}`,'question',{target:l.targets[0].id,facet:facet||l.targets[0].facets[0],stage:'independent',reserve:true,contextKey:`${id}.reserve-${n}`,format:productive?'type':'choice',prompt:'Complete this fresh situation with the taught form or meaning.',context,...(translation?{translation}:{}),answer,...(productive?{}:{options:[answer,...distractors]}),explanation:l.targets[0].explanation,hint:l.targets[0].repair.body,speak:context.replace('___',answer)});
  if(l.targets[0].modality==='reading') q.passageId=`${id}.passage`;
  if(l.targets[0].modality==='listening') {q.audioId=`${id}.passage`; delete q.translation;}
  l.steps.push(q);
}
function oldLesson(level, sourceId, id, opts={}) {
  const src=allOld[sourceId], obj=src.objectives[0], tid=targetId(id);
  if (!src) throw Error(sourceId);
  const cards=(opts.cards||obj.teach).map((c,i)=>step(id,`teach-${i+1}`,'teach',{title:c.title,body:c.body,examples:c.examples,introduces:[tid]}));
  const qs=(opts.questions||obj.questions.filter(q=>q.format!=='match')).slice(0,4);
  if(qs.length!==4) throw Error(`old four checks ${sourceId}`);
  const checks=qs.map((q,i)=>{
    const {id:unused,errorTag,guided,...v}=q;
    return step(id,`check-${i+1}`,'question',{...v,target:tid,facet:opts.facet||'use',stage:i===0?'guided':'independent',contextKey:`${id}.scene-${i+1}`});
  });
  const ex=obj.teach[0].examples[0];
  const t=target(id,opts.label||src.title,opts.targetBody||obj.explanation,ex,[opts.facet||'use']);
  const words=step(id,'words','words',{title:opts.wordsTitle||'Useful words and phrases',body:'Read these meanings before practising the pattern.',words:phraseWords(opts.words||[])});
  if(!words.words.length) throw Error(`words needed ${id}`);
  const passage=opts.passage?step(id,'passage','passage',{title:opts.passage.title,it:opts.passage.it,en:opts.passage.en,mode:opts.passage.mode||'read',...(opts.passage.mode==='listen'?{audioId:`${id}.passage`}:{}),task:opts.passage.task}):null;
  const pf=opts.portfolio||{};
  const application=step(id,'apply','portfolio',{title:pf.title||`Use ${src.title.toLowerCase()} in context`,prompt:pf.prompt||`Write two or three Italian sentences for a realistic situation using this pattern. Then compare with the model.`,mode:pf.mode||'write',model:pf.model||ex.it,rubric:pf.rubric||[`The sentence uses ${src.title.toLowerCase()} to express the intended meaning.`, 'The time, people and reference words remain clear.', 'The sentences read naturally together.'],...(pf.partnerPrompt?{partnerPrompt:pf.partnerPrompt}:{})});
  const recap=step(id,'recap','teach',{title:'What to keep',body:src.takeaway,examples:[obj.teach.at(-1).examples[0]]});
  return register(level,lessonBase(id,opts.title||src.title,opts.outcome||src.outcome,opts.prerequisites||[],src.takeaway,src.related,[t],[words,...cards,checks[0],...(passage?[passage]:[]),...separatedChecks(id,checks.slice(1)),application,recap],[sourceId]));
}
function revisedQuestions(sourceId, edits={}) {
  const qs=structuredClone(allOld[sourceId].objectives[0].questions.filter(q=>q.format!=='match'));
  for(const [index, patch] of Object.entries(edits)) Object.assign(qs[Number(index)],patch);
  return qs;
}
// A compact authored item still contains two distinct model explanations, four
// contextual checks, and a practical application; only JSON ceremony is generated.
function fresh(level, spec) {
  const {id,title,outcome,takeaway,prerequisites=[],words,models,checks,application,passage,facets=['use'],related=[],legacyLessonIds=[],modality='language',passageBeforeGuided=false}=spec;
  if(models.length<2||checks.length<4||!words.length) throw Error(`incomplete authored lesson ${id}`);
  const tid=targetId(id);
  const cards=models.map((m,i)=>step(id,`teach-${i+1}`,'teach',{title:m[0],body:m[1],examples:[{it:m[2],en:m[3]}],introduces:[tid]}));
  const qs=checks.map((q,i)=>{
    const [context,translation,answer,options,explanation,hint,facet='use',accepted]=q;
    const format=Array.isArray(options)?'choice':'type';
    const speak=context.replace('___',answer);
    return step(id,`check-${i+1}`,'question',{target:tid,facet,stage:i===0?'guided':'independent',contextKey:`${id}.scene-${i+1}`,format,prompt:modality==='listening'?'Listen again, then complete the point you heard.':i===0?'Complete the modelled Italian sentence.':'Complete this new Italian sentence.',context,...(translation?{translation}:{}),answer,...(options?{options}:{}),...(accepted?.length?{accepted}:{}),explanation,hint,speak,...(modality==='reading'&&passage?{passageId:`${id}.passage`}:{}),...(modality==='listening'&&passage?{audioId:`${id}.passage`}:{})});
  });
  const pass=passage?step(id,'passage','passage',{title:passage.title,it:passage.it,en:passage.en,mode:passage.mode||'read',...(passage.mode==='listen'?{audioId:`${id}.passage`}:{}),task:passage.task}):null;
  const app=step(id,'apply','portfolio',{title:application[0],prompt:application[1],mode:application[4]||'write',model:application[2],rubric:application[3],...(application[5]?{partnerPrompt:application[5]}:{})});
  const recap=step(id,'recap','teach',{title:'Keep this contrast',body:takeaway,examples:[{it:models[1][2],en:models[1][3]}]});
  const tgt=target(id,title,models.map(m=>m[1]).join(' '),{it:models[0][2],en:models[0][3]},facets);
  tgt.modality=modality;
  return register(level,lessonBase(id,title,outcome,prerequisites,takeaway,related,[tgt],[step(id,'words','words',{title:'Words for the task',body:'Use these meanings as you work through the examples.',words:phraseWords(words)}),...cards,...(passageBeforeGuided&&pass?[pass]:[]),qs[0],...(!passageBeforeGuided&&pass?[pass]:[]),...separatedChecks(id,qs.slice(1)),app,recap],legacyLessonIds));
}
function listeningLesson(level,{id,title,outcome,takeaway,prerequisites,words,models,clips,application}){
  const tid=targetId(id);
  const targetRecord=target(id,title,models.map(m=>m[1]).join(' '),{it:models[0][2],en:models[0][3]},['practical-detail']);
  targetRecord.modality='listening';
  const steps=[step(id,'words','words',{title:'Words to recognize',body:'Listen for changed times, places and requests; the written transcript is available as support.',words:phraseWords(words)}),...models.map((m,i)=>step(id,`teach-${i+1}`,'teach',{title:m[0],body:m[1],examples:[{it:m[2],en:m[3]}],introduces:[tid]}))];
  clips.forEach((c,i)=>{
    const pid=`${id}.clip-${i+1}`;
    steps.push(step(id,`clip-${i+1}`,'passage',{title:c.title,it:c.it,en:c.en,mode:'listen',audioId:pid,task:'Listen for the practical detail before answering.',...(i===clips.length-1?{reserve:true}:{})}));
    const q=step(id,`check-${i+1}`,'question',{target:tid,facet:'practical-detail',stage:i===0?'guided':'independent',contextKey:`${id}.audio-scene-${i+1}`,format:c.options?'choice':'type',prompt:'Listen again and complete the detail from this message.',context:c.context,answer:c.answer,...(c.options?{options:c.options}:{}),explanation:c.explanation,hint:c.hint,speak:c.context.replace('___',c.answer),audioId:pid,...(i===clips.length-1?{reserve:true}:{})});
    steps.push(q);
    if(i>=1&&i<clips.length-2)steps.push(step(id,`contrast-${i}`,'teach',{title:'Check what changed',body:c.explanation,examples:[{it:q.speak,en:c.en}]}));
  });
  // Move the reserve clip and item behind the ungraded application/recap. The
  // engine can still retrieve their stable IDs for a recovery attempt.
  const reservePair=steps.splice(-2);
  steps.push(step(id,'apply','portfolio',{title:application[0],prompt:application[1],mode:application[4]||'mediate',model:application[2],rubric:application[3]}));
  steps.push(step(id,'recap','teach',{title:'Keep the source exact',body:takeaway,examples:[{it:models[1][2],en:models[1][3]}]}));
  steps.push(...reservePair);
  return register(level,lessonBase(id,title,outcome,prerequisites,takeaway,[],[targetRecord],steps));
}
function addContextPassage(level,suffix,mode,title,it,en,task){
  const id=`v2-${level.toLowerCase()}-${suffix}`, lesson=lessons[level][id];
  if(!lesson)throw Error(`passage missing ${id}`);
  const s=step(id,`context-${mode}`,'passage',{title,it,en,mode,task,...(mode==='listen'?{audioId:`${id}.context-${mode}`}:{})});
  const at=lesson.steps.findIndex(x=>x.kind==='portfolio');
  lesson.steps.splice(at,0,s);
}
function setApplication(level,suffix,title,prompt,model,rubric,mode='write'){
  const id=`v2-${level.toLowerCase()}-${suffix}`,lesson=lessons[level][id];
  if(!lesson)throw Error(`application missing ${id}`);
  const at=lesson.steps.findIndex(s=>s.kind==='portfolio');
  lesson.steps[at]=step(id,'apply','portfolio',{title,prompt,model,rubric,mode});
}
register('B1',representative);

const makeUnit=(level,id,title,description,lessonIds)=>({id,title,description,lessons:lessonIds.map(x=>{if(!lessons[level][x])throw Error(`missing ${x}`);return lessons[level][x]})});

