addReserve('B1','earlier-past','Quando Lucia ha chiamato, noi ___ già finito il lavoro.','When Lucia called, we had already finished the work.','avevamo',['abbiamo','avremmo']);
addReserve('B1','earlier-essere','Quando sono arrivato, i miei amici ___ già usciti.','When I arrived, my friends had already gone out.','erano',['avevano','sono']);
