finish('B1',[
  makeUnit('B1','v2-b1-connected-story','Tell what happened','Build a connected account with scene, event, sequence and outcome.',['v2-b1-story-background-event','v2-b1-story-sequence','v2-b1-story-outcome']),
  makeUnit('B1','v2-b1-earlier-past-unit','Explain what happened earlier','Place a cause before another past event and keep agreement clear.',['v2-b1-earlier-past','v2-b1-earlier-essere','v2-b1-earlier-explanation']),
  makeUnit('B1','v2-b1-life-changed','Describe how life changed','Contrast old routines with a particular event and the present.',['v2-b1-past-habits','v2-b1-then-now','v2-b1-changing-duration']),
  makeUnit('B1','v2-b1-give-request','Give and request things','Refer clearly to recipients and objects in messages and requests.',['v2-b1-recipient-reference','v2-b1-double-pronouns','v2-b1-pronoun-request']),
  makeUnit('B1','v2-b1-place-quantity','Places and quantities','Replace a known place, item or amount without losing the referent.',['v2-b1-ci-place','v2-b1-ne-quantity','v2-b1-ce-ne-quantity']),
  makeUnit('B1','v2-b1-identify-people','Identify people and things','Use relative clauses and explicit reference to guide a listener.',['v2-b1-che-cui','v2-b1-relative-prepositions','v2-b1-clarify-reference']),
  makeUnit('B1','v2-b1-workable-plan','Make a workable plan','State real conditions, alternatives and a revised arrangement.',['v2-b1-real-condition','v2-b1-plan-options','v2-b1-revise-plan']),
  makeUnit('B1','v2-b1-explain-problem','Explain a problem','Connect reasons, aims, consequences, obstacles and sequence.',['v2-b1-cause-purpose','v2-b1-consequence-concession','v2-b1-before-after']),
  makeUnit('B1','v2-b1-hopes-doubts','Hopes and doubts','Build and use a limited, explicitly introduced present subjunctive toolkit.',['v2-b1-subjunctive-bridge','v2-b1-opinion-doubt','v2-b1-wishes-feelings','v2-b1-impersonal-judgment']),
  makeUnit('B1','v2-b1-relay-message','Relay a message','Report statements, embed questions and preserve a speaker’s meaning.',['v2-b1-reporting-information','v2-b1-indirect-questions','v2-b1-relay-voicemail']),
  makeUnit('B1','v2-b1-rules-writeback','Read rules and write back','Understand general rules and simple passive service notices.',['v2-b1-impersonal-si','v2-b1-passive-present','v2-b1-read-rules']),
  makeUnit('B1','v2-b1-integration','Everyday independence checkpoint','Apply connected narration, listening, problem solving and mediation in practical situations.',['v2-b1-capstone-account','v2-b1-listen-practical-update','v2-b1-capstone-service','v2-b1-capstone-relay'])
],[{title:'Council of Europe CEFR Companion Volume',url:'https://rm.coe.int/common-european-framework-of-reference-for-languages-learning-teaching/16809ea0d4'},{title:'Profilo della lingua italiana',url:'https://www.unistrapg.it/profilo_lingua_italiana/site/index.html'}]);

// B2.1: productive morphology precedes complex tense relationships.
fresh('B2',{id:'v2-b2-subj-regular',title:'Build present subjunctive forms',outcome:'I can make frequent regular present subjunctive forms across persons.',takeaway:'For regular verbs, -are uses -i and -ere/-ire use -a in the singular and third plural; the noi form matches the present indicative.',prerequisites:['v2-b1-opinion-doubt'],words:[['pensare che','to think that'],['parlare','to speak'],['prendere','to take'],['partire','to leave']],models:[['Build -are forms','Parlare gives parli for io/tu/lui/lei and parlino for loro; parliamo is noi.','Penso che Marta parli con Luca.','I think Marta is talking to Luca.'],['Build -ere and -ire forms','Prendere gives prenda/prendano; partire gives parta/partano.','Spero che loro prendano il treno e partano presto.','I hope they take the train and leave early.']],checks:[['Penso che Marco ___ con il medico oggi.','I think Marco is speaking with the doctor today.','parli',['parli','parla','parlano'],'Parli is the singular present subjunctive of parlare.','Use -i for a regular -are verb.'],['Spero che loro ___ il treno delle sette.','I hope they take the seven o’clock train.','prendano',null,'The third plural present subjunctive of prendere is prendano.','Use -ano for regular -ere.'],['È importante che voi ___ il documento.','It is important that you all read the document.','leggiate',['leggiate','leggete','leggano'],'Leggiate is the voi present subjunctive of leggere.','The voi ending is -iate.'],['Penso che noi ___ prima delle otto.','I think we are leaving before eight.','partiamo',null,'Noi present subjunctive of partire has the same form as present indicative.','Use the noi form already familiar from the present.']],application:['State a small uncertainty','Write two sentences about a possible plan, using two different regular present subjunctive verbs.','Penso che Marta parta domani. Spero che i colleghi prendano il treno con lei.',['Both clauses express a viewpoint or hope.','Two different verb patterns are correctly formed.','The people and planned actions are clear.']],passage:{title:'An uncertain departure',it:'Penso che Marta parta domani. Spero che i colleghi prendano lo stesso treno, ma non so se abbiano già prenotato.',en:'I think Marta is leaving tomorrow. I hope her colleagues take the same train, but I do not know whether they have already booked.',mode:'listen',task:'Notice the viewpoints and the part presented as uncertain.'}});
fresh('B2',{id:'v2-b2-subj-irregular',title:'Use frequent irregular subjunctives',outcome:'I can select common irregular present subjunctive forms in a stated viewpoint.',takeaway:'Learn common irregular forms as short paradigms: sia/siano, abbia/abbiano, vada/vadano, faccia/facciano.',prerequisites:['v2-b2-subj-regular'],words:[['essere','to be'],['avere','to have'],['andare','to go'],['fare','to do']],models:[['Use essere and avere','Essere gives sia/siano; avere gives abbia/abbiano for singular/third plural.','Credo che i ragazzi siano pronti e abbiano i biglietti.','I think the boys are ready and have the tickets.'],['Use andare and fare','Andare gives vada/vadano; fare gives faccia/facciano.','Spero che Sara vada al museo e faccia una visita.','I hope Sara goes to the museum and takes a tour.']],checks:[['Credo che i colleghi ___ pronti.','I think the colleagues are ready.','siano',['siano','sono','sia'],'Siano is the plural present subjunctive of essere.','The subject is plural.'],['Spero che Marta ___ il biglietto.','I hope Marta has the ticket.','abbia',null,'Abbia is the singular present subjunctive of avere.','Use the taught irregular form.'],['Penso che Luca ___ al museo domani.','I think Luca is going to the museum tomorrow.','vada',['vada','va','vadano'],'Vada is the singular present subjunctive of andare.','The subject is Luca.'],['È bene che loro ___ una pausa.','It is good that they take a break.','facciano',null,'Facciano is the plural present subjunctive of fare.','Use the plural irregular form.']],application:['Write a cautious update','Write a short update with one present opinion and one hope, using two different irregular verbs.','Credo che i colleghi abbiano già i biglietti. Spero che vadano al museo domani.',['The opinion and hope are attributed to the speaker.','Two irregular forms are correctly selected.','The account does not present uncertainty as verified fact.']]});
fresh('B2',{id:'v2-b2-fact-or-stance',title:'Separate fact from stance',outcome:'I can distinguish a stated fact from my evaluation of that fact.',takeaway:'So che presents known information; penso/temo che frames a stance and normally takes subjunctive in the taught patterns.',prerequisites:['v2-b2-subj-irregular'],words:[['so che','I know that'],['temo che','I fear that'],['essere aperto','to be open'],['la conferma','confirmation']],models:[['State evidence as known','So che presents information the speaker takes as known.','So che il museo è aperto oggi.','I know the museum is open today.'],['Mark uncertainty or reaction','Temo che states concern, not evidence.','Temo che il museo sia chiuso domani.','I fear the museum may be closed tomorrow.']],checks:[['So che il negozio ___ aperto oggi.','I know the shop is open today.','è',['è','sia','fosse'],'So che presents the opening as known information.','Choose indicative for a known fact.'],['Temo che il negozio ___ chiuso domani.','I fear the shop may be closed tomorrow.','sia',null,'Temo che frames a concern, so use sia.','Use the present subjunctive of essere.'],['So che loro ___ già i biglietti.','I know they already have the tickets.','hanno',['hanno','abbiano','avessero'],'Known information uses hanno here.','The speaker says so che.'],['Penso che loro ___ già i biglietti.','I think they already have the tickets.','abbiano',null,'Penso che frames a current viewpoint, so use abbiano.','Contrast this with the known-fact form.']],application:['Separate source and inference','Write two lines about a planned event: one fact confirmed by a message, and one inference you are not certain about.','So che la riunione è alle nove: ho ricevuto la conferma. Penso che Marta abbia già il programma, ma non gliel’ho chiesto.',['The confirmed fact has an explicit basis.','The inference remains marked as a viewpoint.','The verbal forms fit the difference.']],passage:{title:'What is confirmed?',it:'La mail conferma che la visita è alle dieci. Penso che la guida abbia già i biglietti, ma non ho ancora ricevuto una risposta.',en:'The email confirms that the visit is at ten. I think the guide already has the tickets, but I have not yet received a reply.',mode:'read',task:'Separate the confirmed time from the writer’s inference.'}});

// B2.2: four temporal relations, with paradigms before independent checks.
oldLesson('B2','b2-past-subjunctive','v2-b2-past-subjunctive',{prerequisites:['v2-b2-fact-or-stance'],facet:'earlier-than-present-stance',words:[['già','already'],['finire','to finish'],['perdere il treno','to miss the train'],['uscire','to go out']],cards:[...allOld['b2-past-subjunctive'].objectives[0].teach,{title:'Build singular and plural compound forms',body:'Use present subjunctive of avere or essere plus the participle. Abbia/abbiano and sia/siano mark subject number; with essere, the participle agrees.',examples:[{it:'Penso che Anna sia arrivata e che i ragazzi abbiano perso il treno.',en:'I think Anna arrived and the boys missed the train.'}]}],passage:{title:'Uncertain arrival',it:'Credo che Anna sia già arrivata. Temo che gli altri abbiano perso il treno. So soltanto che la visita comincia alle dieci.',en:'I think Anna has already arrived. I fear the others missed the train. I know only that the visit starts at ten.',mode:'listen',task:'Which events may already have happened, and what is known?'}});
oldLesson('B2','b2-imperfect-subjunctive','v2-b2-imperfect-subjunctive',{prerequisites:['v2-b2-past-subjunctive'],facet:'simultaneous-with-past-stance',words:[['credevo che','I thought that'],['speravamo che','we hoped that'],['essere','to be'],['venire','to come']],cards:[...allOld['b2-imperfect-subjunctive'].objectives[0].teach,{title:'Forms needed here',body:'Essere gives fossi/fosse/fossero; venire gives venissi/veniste; conoscere gives conoscesse; avere gives avessero. These forms put the clause inside a past viewpoint.',examples:[{it:'Speravamo che voi veniste e credevo che loro avessero tempo.',en:'We hoped you would come and I thought they had time.'}]}]});
oldLesson('B2','b2-pluperfect-subjunctive','v2-b2-pluperfect-subjunctive',{prerequisites:['v2-b2-imperfect-subjunctive'],facet:'earlier-than-past-stance',words:[['pensavo che','I thought that'],['già','already'],['pagare il conto','to pay the bill'],['ricevere la lettera','to receive the letter']],cards:[...allOld['b2-pluperfect-subjunctive'].objectives[0].teach,{title:'Auxiliary and participle agreement',body:'The earlier clause uses avesse/avessero or fosse/fossero plus a participle. A movement or reflexive verb uses essere; the participle agrees with that subject.',examples:[{it:'Temevo che Maria si fosse persa e credevo che loro avessero pagato.',en:'I feared Maria had got lost and believed they had paid.'}]}]});
oldLesson('B2','b2-tense-relations','v2-b2-tense-relations',{prerequisites:['v2-b2-pluperfect-subjunctive'],facet:'time-relative-to-stance',words:[['alle otto','at eight'],['il giorno dopo','the next day'],['già','already'],['ancora','still']],portfolio:{title:'Compare two reports',prompt:'Write what you believed at one past moment about an action ongoing then, one already finished, and one expected later.',model:'Alle otto credevo che Marta fosse ancora al lavoro. Pensavo che Anna fosse già tornata e speravo che Luca arrivasse il giorno dopo.',rubric:['Each clause has an explicit past viewpoint.','One event is simultaneous, one earlier, one later.','The time cues make the differences understandable.']}});

// B2.3: unreal conditions only after the imperfect subjunctive is formed.
oldLesson('B2','b1-hypothetical-present','v2-b2-unreal-present',{prerequisites:['v2-b2-tense-relations'],facet:'unreal-present-condition-result',title:'If things were different now',outcome:'I can imagine a different present situation and its possible result.',words:[['se avessi','if I had'],['se fossi','if I were'],['leggerei','I would read'],['resterei','I would stay']],passage:{title:'A different schedule',it:'Se avessi più tempo, frequenterei un corso serale. Se lavorassi più vicino a casa, tornerei prima e potrei leggere ogni sera.',en:'If I had more time, I would take an evening course. If I worked closer to home, I would come home earlier and could read every evening.',mode:'listen',task:'Separate unreal present conditions from imagined results.'},portfolio:{title:'Imagine one change',prompt:'Write two sentences: one unlikely present condition and the result that would follow.',model:'Se abitassi più vicino al lavoro, andrei a piedi ogni mattina. Per ora prendo l’autobus.',rubric:['The se clause uses imperfect subjunctive.','The imagined present result uses present conditional.','The actual present situation remains distinct.']}});
oldLesson('B2','b2-past-conditional','v2-b2-past-conditional',{prerequisites:['v2-b2-unreal-present'],facet:'unreal-past-result',words:[['ma','but'],['il numero','number'],['aiutare','to help'],['rimanere','to stay']],passage:{title:'A missed opportunity',it:'Ti avrei chiamato, ma non avevo il tuo numero. Sara sarebbe venuta con noi, ma era malata. Alla fine siamo partiti in due.',en:'I would have called you, but I did not have your number. Sara would have come with us, but she was ill. In the end only two of us left.',mode:'listen',task:'Identify what did not happen and why.'}});
oldLesson('B2','b2-unreal-past','v2-b2-unreal-past',{prerequisites:['v2-b2-past-conditional'],facet:'unreal-past-condition-result',words:[['se','if'],['partire prima','to leave earlier'],['prendere il treno','to catch the train'],['rispondere','to reply']],portfolio:{title:'Reflect on a missed connection',prompt:'Write two counterfactual sentences about a missed opportunity, preserving what did and did not happen.',model:'Se fossimo partiti prima, avremmo preso il treno. Non siamo partiti prima, quindi lo abbiamo perso.',rubric:['The se clause uses the past unreal condition.','The result uses past conditional.','The factual explanation does not imply the imaginary event really happened.']}});
oldLesson('B2','b2-mixed-condition','v2-b2-mixed-condition',{prerequisites:['v2-b2-unreal-past'],facet:'past-cause-present-result',words:[['adesso / ora','now'],['l’ombrello','umbrella'],['bagnato','wet'],['capire','to understand']],portfolio:{title:'Explain a present consequence',prompt:'Write a short reflection on a past choice and its consequence now.',model:'Se avessi preso il treno ieri, ora sarei già a casa. Invece sono ancora qui.',rubric:['The imagined cause belongs to the past.','The imagined consequence belongs to now.','The actual situation is not confused with the counterfactual.']}});

// B2.4: reports adjust speaker, time and place references, with source wording visible.
oldLesson('B2','b2-reported-past','v2-b2-reported-past',{prerequisites:['v2-b2-mixed-condition'],facet:'past-viewpoint-report',words:[['disse','said (literary past)'],['ha detto','said'],['quel giorno','that day'],['aveva perso','had lost']],cards:[...allOld['b2-reported-past'].objectives[0].teach,{title:'Reporting verbs as supplied background',body:'Disse is a literary past form of dire; here it is given as part of the source, not tested. When a report is anchored in the past, a former present often becomes imperfetto and a former completed event may become trapassato.',examples:[{it:'«Parto oggi». Marco disse che partiva quel giorno.',en:'“I’m leaving today.” Marco said he was leaving that day.'}]}],passage:{title:'What Marco said',it:'Marco ieri ha detto: «Parto oggi; ho già comprato il biglietto». Oggi Anna racconta che Marco partiva quel giorno e aveva già comprato il biglietto.',en:'Yesterday Marco said: “I am leaving today; I have already bought the ticket.” Today Anna recounts that Marco was leaving that day and had already bought the ticket.',mode:'listen',task:'Notice the change of viewpoint from Marco to Anna.'}});
oldLesson('B2','b2-reported-questions','v2-b2-reported-questions',{prerequisites:['v2-b2-reported-past'],facet:'reported-question-reference',words:[['mi chiese','asked me (literary past)'],['mi domandò','asked me (literary past)'],['il giorno dopo','the following day'],['se','whether']],cards:[...allOld['b2-reported-questions'].objectives[0].teach,{title:'Past reporting verbs are given',body:'Chiese and domandò are fixed literary past forms in these source lines. The target is the embedded question and adjusted reference words, not producing passato remoto.',examples:[{it:'«Vieni domani?» Mi chiese se sarei venuto il giorno dopo.',en:'“Are you coming tomorrow?” He asked whether I would come the next day.'}]}]});
oldLesson('B2','b2-reported-commands','v2-b2-reported-commands',{prerequisites:['v2-b2-reported-questions'],facet:'reported-instruction',words:[['chiudere','to close'],['aspettare','to wait'],['il capo','manager'],['presto','early']],portfolio:{title:'Relay meeting notes',prompt:'Write a short note reporting one factual update, one question and one instruction from a meeting.',model:'Anna ha detto che la sala era occupata. Mi ha chiesto se avevo un’altra stanza e ci ha detto di aspettare vicino all’ingresso.',rubric:['The factual update stays a statement.','The question remains a question of missing information.','The instruction uses di plus infinitive and keeps the recipient clear.']}});

// B2.5: institution-focused voice across tenses and agreement.
oldLesson('B2','b2-passive-tenses','v2-b2-passive-tenses',{prerequisites:['v2-b2-reported-commands'],facet:'passive-across-time',words:[['la mostra','exhibition'],['i documenti','documents'],['firmare','to sign'],['inaugurare','to open officially']],questions:revisedQuestions('b2-passive-tenses',{2:{context:'Quando sono arrivato ieri, il negozio ___ già stato chiuso.',translation:'When I arrived yesterday, the shop had already been closed.',speak:'Quando sono arrivato ieri, il negozio era già stato chiuso.'}}),passage:{title:'An institutional update',it:'La mostra sarà aperta domani. I documenti sono stati firmati ieri e gli inviti erano già stati spediti lunedì.',en:'The exhibition will open tomorrow. The documents were signed yesterday and the invitations had already been sent on Monday.',mode:'listen',task:'Separate future, completed and earlier passive events.'}});
oldLesson('B2','b2-si-passivante','v2-b2-si-passivante',{prerequisites:['v2-b2-passive-tenses'],facet:'thing-agreement',words:[['vendere','to sell'],['affittare','to rent'],['trovare','to find'],['prestare','to lend']],portfolio:{title:'Rewrite a public notice',prompt:'Write two clear public notices with si passivante, one singular and one plural.',model:'Si affitta una stanza da ottobre. In biblioteca si prestano libri per due settimane.',rubric:['The thing acted on is singular in one notice and plural in the other.','The verb agrees with that thing.','Each notice gives usable public information.']}});
fresh('B2',{id:'v2-b2-agent-and-focus',title:'Choose whether to name the actor',outcome:'I can decide whether an institutional message needs an agent.',takeaway:'Passive can omit an irrelevant actor or add da plus the responsible actor when that identity matters.',prerequisites:['v2-b2-si-passivante'],words:[['la richiesta','request'],['esaminare','to examine'],['il comitato','committee'],['pubblicare','to publish']],models:[['Focus the affected item','When the process matters more than the staff, omit the actor.','Le richieste saranno esaminate domani.','The requests will be examined tomorrow.'],['Name responsibility when needed','Da introduces a specific responsible actor.','Le richieste saranno esaminate dal comitato.','The requests will be examined by the committee.']],checks:[['Le domande saranno valutate ___ commissione.','The applications will be evaluated by the committee.','dalla',['dalla','alla','nella'],'Dalla marks the passive agent.','Who is responsible for evaluating?'],['Il documento è stato firmato ___ direttore.','The document was signed by the director.','dal',null,'Dal introduces the person who signed.','Use da plus il.'],['Le informazioni sono state pubblicate ___.','The information was published by the municipality.','dal comune',['dal comune','al comune','nel comune'],'Dal comune marks the actor, not the destination.','Choose the by-agent phrase.'],['La risposta sarà inviata ___ segreteria.','The reply will be sent by the office.','dalla',null,'Dalla segreteria identifies the sending institution.','Use da plus la.']],application:['Edit a service notice','Write a two-sentence institutional notice: one passive without an actor, then one naming the responsible office because readers need it.','Le richieste saranno esaminate entro venerdì. La risposta sarà inviata dalla segreteria lunedì.',['The first sentence foregrounds the process.','The second names the responsible actor accurately.','The timeline helps the reader know what to expect.']]} );

// B2.6: precision of reference, topic and contrastive focus.
oldLesson('B2','b2-complex-relatives','v2-b2-complex-relatives',{prerequisites:['v2-b2-agent-and-focus'],facet:'explicit-relative-reference',words:[['le colleghe','colleagues (women)'],['il direttore','director'],['il documento','document'],['la chiarezza','clarity']],passage:{title:'Which document?',it:'Ho incontrato le colleghe del progetto, le quali conoscono il direttore. Mi hanno mostrato il documento sul quale lavoriamo. Ciò che conta ora è la firma.',en:'I met the project colleagues, who know the director. They showed me the document we are working on. What matters now is the signature.',mode:'listen',task:'Identify the people, document and main point.'}});
oldLesson('B2','b2-cleft-focus','v2-b2-cleft-focus',{prerequisites:['v2-b2-complex-relatives'],facet:'contrastive-focus',words:[['non Luca','not Luca'],['alle otto','at eight'],['scegliere','to choose'],['il ristorante','restaurant']],portfolio:{title:'Correct a mistaken detail',prompt:'Write three brief corrections: one person, one time and one place, making the corrected element prominent.',model:'È Marta che ha chiamato, non Luca. È alle otto che parte il treno, non alle nove.',rubric:['The corrected element is the focus.','The contrast is accurate and specific.','The rest of each proposition remains unchanged.']}});
oldLesson('B2','b2-dislocation','v2-b2-dislocation',{prerequisites:['v2-b2-cleft-focus'],facet:'known-topic-resumption',words:[['la lettera','letter'],['i film','films'],['di questo tema','about this topic'],['conoscere','to know']],cards:[...allOld['b2-dislocation'].objectives[0].teach,{title:'Agreement after a preceding object clitic',body:'With lo/la/li/le before a compound past verb, the participle agrees with that direct object: la lettera, l’ho scritta; i film, li ho visti. Ne resumes a di phrase separately.',examples:[{it:'La lettera, l’ho scritta ieri. Quei film, li ho già visti.',en:'The letter, I wrote it yesterday. Those films, I have already seen them.'}]}]});

// B2.7: condensation is governed by who performs the action.
oldLesson('B2','b2-infinitive-clauses','v2-b2-infinitive-clauses',{prerequisites:['v2-b2-dislocation'],facet:'same-subject-infinitive',words:[['decidere di','to decide to'],['dopo aver','after having'],['la mail','email'],['scusarsi','to apologize']],cards:[...allOld['b2-infinitive-clauses'].objectives[0].teach,{title:'Completed action before another action',body:'Dopo aver letto and per aver risposto use aver plus a participle. The understood actor is the subject of the main clause.',examples:[{it:'Dopo aver letto la mail, ho chiamato Marco.',en:'After reading the email, I called Marco.'}]}],passage:{title:'A concise explanation',it:'Dopo aver letto la mail, Sara ha chiamato il cliente. Ha deciso di spostare la riunione e si è scusata per aver risposto tardi.',en:'After reading the email, Sara called the client. She decided to move the meeting and apologized for replying late.',mode:'listen',task:'Track the actor of each shortened clause.'}});
oldLesson('B2','b2-gerund-clauses','v2-b2-gerund-clauses',{prerequisites:['v2-b2-infinitive-clauses'],facet:'same-actor-gerund',words:[['camminando','while walking'],['ascoltando','by listening'],['la notizia','news item'],['l’annuncio','advertisement']],cards:[...allOld['b2-gerund-clauses'].objectives[0].teach,{title:'A prior action: avendo plus participle',body:'Avendo sentito locates the same actor’s hearing before the main action. Do not use a gerund if the actor changes between clauses.',examples:[{it:'Avendo sentito la notizia, Marta è uscita subito.',en:'Having heard the news, Marta went out at once.'}]}]});
fresh('B2',{id:'v2-b2-actor-control',title:'Keep the actor of a short clause clear',outcome:'I can avoid shortening a clause when the actor would change.',takeaway:'An infinitive or gerund normally inherits a recoverable actor; when the actor changes, use a full clause.',prerequisites:['v2-b2-gerund-clauses'],words:[['mentre','while'],['dopo che','after'],['guidare','to drive'],['telefonare','to call']],models:[['Shorten only with the same actor','In the model, Paolo both walks and hears the music.','Camminando, Paolo ascoltava la musica.','While walking, Paolo listened to music.'],['Keep a full clause for a different actor','If Anna phones while Paolo drives, name both people in finite clauses.','Mentre Paolo guidava, Anna ha telefonato.','While Paolo was driving, Anna called.']],checks:[['___, Paolo ascoltava la radio.','While walking, Paolo listened to the radio.','Camminando',['Camminando','Mentre Anna camminava','Avendo camminato'],'Paolo is the actor in both actions.','The same person walks and listens.'],['___ Paolo guidava, Anna ha telefonato.','While Paolo was driving, Anna called.','Mentre',null,'Different actors require a full finite clause.','Keep Paolo as the explicit subject.'],['Dopo ___ il messaggio, Sara ha risposto.','After reading the message, Sara replied.','aver letto',['aver letto','che Luca ha letto','leggendo'],'Sara performs both actions, and the reading came first.','Use the prior-action infinitive.'],['Dopo che Anna ___, Paolo ha chiuso la porta.','After Anna left, Paolo closed the door.','è uscita',null,'Anna and Paolo differ, so the first clause stays finite.','Complete Anna’s action rather than using an infinitive.']],application:['Edit a short report','Rewrite two sentences in a brief report: shorten a same-actor sequence, but keep a changed-actor sequence explicit.','Dopo aver letto la mail, Marta ha risposto. Mentre Marta scriveva, Luca ha telefonato.',['The shortened clause has the same actor as its main clause.','The different-actor clause names both participants.','Time order remains accurate.']]} );

// B2.8: compare evidence and make the argument traceable.
oldLesson('B2','b2-argument-links','v2-b2-argument-links',{prerequisites:['v2-b2-actor-control'],facet:'argument-relation',words:[['inoltre','furthermore'],['pertanto','therefore'],['tuttavia','however'],['i fondi','funds']],passage:{title:'A proposal in brief',it:'Il servizio è rapido. Inoltre, costa meno del precedente. Tuttavia, non copre tutte le zone; pertanto, servirà un piano alternativo per alcuni utenti.',en:'The service is fast. Furthermore, it costs less than the previous one. However, it does not cover every area; therefore, some users will need an alternative plan.',mode:'listen',task:'Identify addition, limitation and consequence.'}});
fresh('B2',{id:'v2-b2-evidence-source',title:'Separate a source from an inference',outcome:'I can report a short source accurately and label my own inference.',takeaway:'A reliable comparison names what a source states before drawing a separate conclusion; without an earlier measure, improvement is unproven.',prerequisites:['v2-b2-argument-links'],words:[['secondo il rapporto','according to the report'],['il campione','sample'],['la metà','half'],['il confronto','comparison']],models:[['Attribute a reported figure','A source example can report a figure without proving a wider claim.','Secondo un sondaggio, trenta persone su sessanta usano l’autobus.','According to a survey, thirty out of sixty people use the bus.'],['Mark the limit of an inference','The example has no earlier figure, so it cannot establish an improvement over time.','Senza un confronto precedente, non possiamo dire che l’uso sia aumentato.','Without an earlier comparison, we cannot say that use has risen.']],checks:[['Secondo il rapporto, ___ utenti su cento hanno aspettato meno di dieci minuti.','','cinquanta',['cinquanta','venti','trenta'],'Fifty users waited less than ten minutes.','Find the first group in the report.'],['Il rapporto comprende in tutto ___ utenti.','','cento',null,'The report covers one hundred users.','Find the sample total.'],['Hanno aspettato più di venti minuti ___ utenti.','','venti',['venti','trenta','cinquanta'],'Twenty users are in the longest-wait group.','Keep the three groups separate.'],['Il rapporto non confronta i risultati con l’anno ___.','','precedente',null,'No previous-year comparison is included.','Find the report’s stated limitation.']],application:['Summarize a small report','Read the report, write two attributed figures, then state one limitation that prevents a trend claim.','Secondo il rapporto, cinquanta utenti su cento hanno aspettato meno di dieci minuti e venti più di venti minuti. I dati descrivono questo gruppo, ma non dimostrano un miglioramento: manca un confronto con l’anno precedente. Per valutare un cambiamento servirebbero dati comparabili di un periodo precedente.',['The figures and denominator are accurate.','No improvement is claimed without a baseline.','The limitation is connected to the proposed next evidence.'],'mediate'],passage:{title:'Queue survey',it:'Un rapporto su 100 utenti indica che 50 hanno aspettato meno di dieci minuti; 30 hanno aspettato tra dieci e venti minuti; 20 hanno aspettato più di venti minuti. Il rapporto non confronta i risultati con l’anno precedente.',en:'A report on 100 users says that 50 waited less than ten minutes; 30 waited between ten and twenty minutes; 20 waited more than twenty minutes. The report does not compare the results with last year.',mode:'read',task:'Preserve the figures and state what the report cannot show.'},modality:'reading',passageBeforeGuided:true});
fresh('B2',{id:'v2-b2-compare-options',title:'Compare two workable options',outcome:'I can compare benefits and limits before recommending an option for a particular need.',takeaway:'An argument should say which option serves which need; a cheap option is not automatically the fastest or most accessible.',prerequisites:['v2-b2-evidence-source'],words:[['il costo','cost'],['la durata','duration'],['accessibile','accessible'],['la scelta','choice']],models:[['Compare on one criterion','State exactly what is cheaper, faster or more accessible.','Il treno costa meno dell’autobus, ma parte più tardi.','The train costs less than the bus, but leaves later.'],['Link recommendation to a need','A recommendation depends on the traveller’s priority.','Se dobbiamo arrivare presto, sceglierei l’autobus.','If we need to arrive early, I would choose the bus.']],checks:[['Il treno costa meno; ___ parte più tardi.','The train costs less; however, it leaves later.','tuttavia',['tuttavia','pertanto','inoltre'],'Tuttavia introduces a counterpoint.','The second fact limits the first.'],['Se conta soprattutto il prezzo, ___ il treno.','If price matters most, I would choose the train.','sceglierei',null,'The cheaper option fits the stated priority.','Use the conditional recommendation.'],['L’autobus parte prima; ___ è più adatto a chi ha fretta.','The bus leaves earlier; therefore it suits someone in a hurry better.','pertanto',['pertanto','tuttavia','anche se'],'Pertanto draws a consequence from the earlier departure.','The second clause follows from the first.'],['Se l’accessibilità è essenziale, dobbiamo ___ prima di scegliere.','If accessibility is essential, we must check it before choosing.','verificarla',null,'The available comparison does not state accessibility, so verify it.','Do not invent an unstated feature.']],application:['Recommend an option','Compare the train and bus information for a traveller who must arrive before nine, then make a recommendation and name one unknown.','L’autobus arriva alle 8:40, quindi è più sicuro per chi deve essere lì prima delle nove. Il treno costa meno ma arriva alle 9:10. Non sappiamo quale mezzo sia più accessibile.',['The recommendation fits the stated deadline.','Prices and arrival times are preserved.','At least one unstated criterion is identified as unknown.'],'mediate'],passage:{title:'Two routes',it:'Treno: 8 euro; partenza 8:20, arrivo 9:10. Autobus: 10 euro; partenza 7:50, arrivo 8:40. Le informazioni non indicano l’accessibilità dei due mezzi.',en:'Train: 8 euros; departure 8:20, arrival 9:10. Bus: 10 euros; departure 7:50, arrival 8:40. The information does not state the accessibility of either service.',mode:'read',task:'Choose for a deadline while acknowledging the unknown.'}});

// B2.9: recognize an obstacle, then respond without changing the other position.
oldLesson('B2','b2-concession-contrast','v2-b2-concession-contrast',{prerequisites:['v2-b2-compare-options'],facet:'factual-versus-possible-obstacle',words:[['benché','although'],['sebbene','although'],['nonostante','despite'],['il traffico','traffic']],passage:{title:'A difficult proposal',it:'Nonostante il costo, il progetto potrebbe essere utile. Benché sia tardi, discuteremo ancora un punto: chi lo pagherà?',en:'Despite the cost, the project could be useful. Although it is late, we will discuss one more point: who will pay for it?',mode:'listen',task:'Identify the conceded cost and the remaining question.'}});
fresh('B2',{id:'v2-b2-respond-objection',title:'Respond to an objection fairly',outcome:'I can acknowledge a valid objection and answer it with a specific reason.',takeaway:'Conceding a limitation makes the argument more precise; the response must address that limitation, not a different claim.',prerequisites:['v2-b2-concession-contrast'],words:[['l’obiezione','objection'],['il costo iniziale','initial cost'],['nel lungo periodo','in the long run'],['ridurre','to reduce']],models:[['Acknowledge the objection','Say what the other person actually raised.','È vero che il costo iniziale è alto.','It is true that the initial cost is high.'],['Answer with a relevant reason','Use a reason tied to that cost, not an unrelated benefit.','Tuttavia, il nuovo sistema ridurrà le spese mensili.','However, the new system will reduce monthly expenses.']],checks:[['È vero che il costo iniziale è alto; ___ le spese mensili diminuiranno.','It is true the initial cost is high; however, monthly expenses will decrease.','tuttavia',['tuttavia','inoltre','perché'],'Tuttavia introduces a relevant counterpoint.','The second clause responds to the concern.'],['L’obiezione riguarda il costo; nella risposta devo parlare del ___.','The objection concerns cost; in the response I need to discuss cost.','costo',null,'Address the original concern rather than changing topic.','Repeat the disputed criterion.'],['«Il servizio è lento». Una risposta pertinente è: «___, ma sarà più rapido dopo l’aggiornamento».','“The service is slow.” A relevant answer is: “That is true, but it will be faster after the update.”','È vero',['È vero','Non costa','È vicino'],'È vero acknowledges the claim before responding.','Acknowledge, then answer.'],['Anche se il piano richiede tempo, ___ il numero degli errori.','Even if the plan takes time, it will reduce the number of errors.','ridurrà',null,'The future benefit addresses the time investment.','Use the planned result of the change.']],application:['Reply in a short meeting','Respond to a colleague who says the new system costs too much. Acknowledge the cost, give one relevant benefit and state what evidence is still needed.','È vero che il costo iniziale è alto. Tuttavia, se riduce le spese mensili, può essere utile. Prima di decidere, dobbiamo verificare i dati sui risparmi.',['The objection is represented accurately.','The response is relevant rather than dismissive.','An unknown is left as an evidence need.'],'interact','A partner can challenge the claimed future savings; respond without asserting unverified numbers.']});
fresh('B2',{id:'v2-b2-clarify-intent',title:'Clarify what you do and do not claim',outcome:'I can narrow a claim when a listener reads too much into it.',takeaway:'Non dico che..., dico che... explicitly separates the rejected inference from the intended point.',prerequisites:['v2-b2-respond-objection'],words:[['intendere','to mean'],['sostenere','to claim'],['non significa che','does not mean that'],['chiarire','to clarify']],models:[['Reject the misreading','Negate only the claim you did not make.','Non dico che il piano sia perfetto.','I am not saying that the plan is perfect.'],['Restate the intended point','State the narrower position explicitly.','Dico che può ridurre i tempi di attesa.','I am saying it can reduce waiting times.']],checks:[['Non dico che il progetto ___ perfetto.','I am not saying that the project is perfect.','sia',['sia','è','era'],'Sia remains inside the denied claim.','Use the subjunctive in non dico che here.'],['Dico soltanto che il progetto ___ ridurre l’attesa.','I am only saying the project can reduce waiting times.','può',null,'Può preserves the modest claim of possibility.','Do not turn can into will.'],['«Può aiutare» non significa «___ sicuramente».','“It can help” does not mean “it will certainly help.”','aiuterà',['aiuterà','può aiutare','potrebbe aiutare'],'The certain future is the overstatement being rejected.','Find the stronger claim.'],['Non sostengo che il dato ___ tutti gli utenti; riguarda solo un campione.','I do not claim the figure represents all users; it concerns only a sample.','rappresenti',null,'The denied broad claim takes the subjunctive.','Keep the sample limitation.']],application:['Correct a misreading','Write a brief reply to someone who says you promised a guaranteed result, when you only said the proposal might help.','Non ho detto che il progetto risolverà certamente il problema. Ho detto che potrebbe ridurre i tempi di attesa; servono altri dati per valutarlo.',['The original modest claim is preserved.','The overstatement is explicitly rejected.','No new certainty is invented.']]} );

// B2.10: correspondence moves from evidence and request to negotiation and remedy.
fresh('B2',{id:'v2-b2-complaint-facts',title:'State a complaint with verifiable facts',outcome:'I can describe a service problem without replacing dates or facts with blame.',takeaway:'A useful complaint gives the order, promised date, actual event and requested action.',prerequisites:['v2-b2-clarify-intent'],words:[['l’ordine','order'],['la consegna','delivery'],['previsto','scheduled'],['il rimborso','refund']],models:[['Give the reference and promise','Name the item or service and the agreed date.','Il mio ordine 42 doveva arrivare lunedì.','My order 42 was due to arrive Monday.'],['State the actual problem and request','Describe what occurred, then make a specific request.','È arrivato giovedì; chiedo un rimborso delle spese di consegna.','It arrived Thursday; I request a refund of the delivery charges.']],checks:[['L’ordine doveva arrivare lunedì; è arrivato ___.','The order was due Monday; it arrived Thursday.','giovedì',['giovedì','lunedì','domani'],'Giovedì preserves the actual delivery date.','Report the later day, not the promised one.'],['Chiedo il rimborso delle spese di ___.','I request a refund of the delivery charges.','consegna',null,'The requested refund concerns delivery costs.','Name the cost precisely.'],['Il prodotto non funziona; ___ una sostituzione.','The product does not work; I request a replacement.','chiedo',['chiedo','pretendo sempre','ignoro'],'Chiedo makes the remedy explicit without inventing other facts.','State a specific action sought.'],['Ho ricevuto solo due pezzi, ma nell’ordine ne erano ___.','I received only two items, but the order listed three.','tre',null,'The quantity discrepancy is the verifiable problem.','Preserve the ordered quantity.']],application:['Write a service complaint','Write a 70–100 word email using the reference, expected and actual delivery, and one specific remedy.','Buongiorno, scrivo per l’ordine 42. La consegna era prevista per lunedì, ma il pacco è arrivato giovedì. Chiedo il rimborso delle spese di consegna. Potete confermarmi quando riceverò una risposta? Cordiali saluti.',['The reference, dates and facts are accurate.','The requested remedy is specific and proportionate.','The register is polite and direct.']],passage:{title:'Order confirmation',it:'Ordine 42: tre pezzi. Consegna prevista lunedì 12 maggio. Spese di consegna: 6 euro. Il tracciamento indica consegna avvenuta giovedì 15 maggio.',en:'Order 42: three items. Delivery expected Monday 12 May. Delivery charge: 6 euros. Tracking shows delivery on Thursday 15 May.',mode:'read',task:'Use the dates and charges accurately in your complaint.'}});
fresh('B2',{id:'v2-b2-negotiate-compromise',title:'Propose a workable compromise',outcome:'I can acknowledge a constraint and suggest an option with conditions.',takeaway:'A compromise names the shared aim, the constraint and what each side would do next.',prerequisites:['v2-b2-complaint-facts'],words:[['la scadenza','deadline'],['posticipare','to postpone'],['a condizione che','provided that'],['confermare','to confirm']],models:[['Recognize the constraint','Acknowledge what the other side cannot change.','Capisco che la consegna venerdì non sia possibile.','I understand that Friday delivery is not possible.'],['Make a conditional proposal','A condizione che is followed by subjunctive in this proposal.','Posso accettare lunedì, a condizione che mi confermiate l’orario.','I can accept Monday, provided you confirm the time.']],checks:[['Posso accettare lunedì, a condizione che mi ___ l’orario.','I can accept Monday, provided you confirm the time to me.','confermiate',['confermiate','confermate','confermavate'],'A condizione che takes a subjunctive; voi is confermiate.','The condition is a required confirmation.'],['Capisco che venerdì non ___ possibile; lunedì va bene.','I understand Friday is not possible; Monday is fine.','sia',null,'Capisco che here acknowledges a constraint in a subordinate clause; sia fits the modelled stance.','Use the frequent present subjunctive of essere.'],['Se mi inviate il documento oggi, ___ controllarlo domani.','If you send me the document today, I can check it tomorrow.','posso',['posso','potessi','potuto'],'This is an open practical arrangement.','Use the present response to a real condition.'],['Accetto il nuovo orario, ___ che il cliente sia informato.','I accept the new time, provided the client is informed.','a condizione',null,'A condizione che makes the necessary term explicit.','State the condition rather than an unconditional acceptance.']],application:['Negotiate a delivery change','With a partner, propose a new delivery time after Friday becomes unavailable. State what confirmation you need.','— Venerdì non riusciamo a consegnare.\n— Capisco. Posso accettare lunedì, a condizione che mi confermiate una fascia oraria entro oggi.',['The original constraint is acknowledged.','The replacement time is specific.','The required confirmation and deadline are clear.'],'interact','The partner offers a different time window; respond with a justified acceptance or alternative.']});
fresh('B2',{id:'v2-b2-reply-remedy',title:'Reply with a concrete remedy',outcome:'I can answer a complaint by acknowledging facts, offering a remedy and stating a deadline.',takeaway:'A service reply should address the reported problem and say what will happen next, by whom and when.',prerequisites:['v2-b2-negotiate-compromise'],words:[['ci scusiamo','we apologize'],['accreditare','to credit'],['entro venerdì','by Friday'],['la verifica','check']],models:[['Acknowledge the actual issue','Name the delayed delivery rather than using a vague apology.','Ci scusiamo per il ritardo nella consegna dell’ordine 42.','We apologize for the delay in delivering order 42.'],['Make the remedy checkable','State the refund and a deadline.','Rimborseremo i sei euro delle spese di consegna entro venerdì.','We will refund the six euros in delivery charges by Friday.']],checks:[['Ci scusiamo per il ___ nella consegna dell’ordine 42.','We apologize for the delay in delivering order 42.','ritardo',['ritardo','prezzo','colore'],'Ritardo names the reported problem.','Use the actual complaint.'],['Rimborseremo le spese di consegna ___ venerdì.','We will refund the delivery charges by Friday.','entro',null,'Entro gives the promised deadline.','State by when, not just when.'],['Il rimborso riguarda ___ euro di consegna.','The refund concerns six euros in delivery charges.','sei',['sei','tre','dodici'],'Six euros is the charge in the confirmation.','Keep the amount exact.'],['Se non riceve il rimborso entro venerdì, ci ___ di nuovo.','If you do not receive the refund by Friday, please contact us again.','contatti',null,'The formal Lei command asks the customer to contact the office.','Use formal Lei, not familiar tu.']],application:['Send the reply','Write a polite reply to the order complaint, with an acknowledgement, remedy, deadline and contact route.','Gentile cliente, ci scusiamo per il ritardo dell’ordine 42. Rimborseremo i sei euro delle spese di consegna entro venerdì. Se non riceve il rimborso, ci contatti di nuovo. Cordiali saluti.',['The complaint is acknowledged accurately.','The remedy and amount match the source.','The deadline and next contact step are explicit.']]} );

// B2.11: recognize literary narrative forms without using them as default conversation.
oldLesson('B2','b2-passato-remoto','v2-b2-passato-remoto',{prerequisites:['v2-b2-reply-remedy'],facet:'literary-bounded-event',words:[['nel racconto','in the story'],['vide','saw'],['disse','said'],['si trasferì','moved']],cards:[...allOld['b2-passato-remoto'].objectives[0].teach,{title:'A further common written form',body:'Trasferirsi appears as si trasferì for lui/lei in a written historical narrative. It is supplied here before the short cloze; ordinary spoken accounts often use passato prossimo instead.',examples:[{it:'Nel 1900 la famiglia si trasferì a Torino.',en:'In 1900 the family moved to Turin.'}]}],passage:{title:'A written episode',it:'Nel 1900 la famiglia si trasferì a Torino. Il figlio entrò nella nuova casa e vide una lettera sul tavolo. La lesse e uscì.',en:'In 1900 the family moved to Turin. The son entered the new house and saw a letter on the table. He read it and went out.',mode:'listen',task:'Notice how the written story advances through bounded events.'}});
oldLesson('B2','b2-remote-pluperfect','v2-b2-remote-pluperfect',{prerequisites:['v2-b2-passato-remoto'],facet:'written-prior-event',words:[['appena','as soon as'],['ebbe finito','had finished'],['fu arrivata','had arrived'],['applaudire','to applaud']],portfolio:{title:'Annotate a historical account',prompt:'Mark a remote-past event and a prior event in a short written narrative, then paraphrase both in conversational Italian.',model:'Appena ebbe finito, uscì. In una conversazione: appena ha finito, è uscito.',rubric:['The earlier event is clearly identified.','The conversational paraphrase preserves the order.','The literary form is recognized as written register.']}});
fresh('B2',{id:'v2-b2-report-versus-story',title:'Choose narrative register',outcome:'I can recognize a written remote-past account and retell its events in natural conversation.',takeaway:'Passato remoto is common in some written narrative and regional speech; a conversational retelling may use passato prossimo while keeping the same chronology.',prerequisites:['v2-b2-remote-pluperfect'],words:[['nacque','was born'],['aprì','opened'],['l’archivio','archive'],['il documento','document']],models:[['Read the written sequence','Remote forms can move a historical account through completed events.','Nel 1905 aprì l’archivio e trovò il documento.','In 1905 he opened the archive and found the document.'],['Retell it conversationally','A spoken report can use passato prossimo without changing the facts.','Nel 1905 ha aperto l’archivio e ha trovato il documento.','In 1905 he opened the archive and found the document.']],checks:[['Nel racconto scritto, il medico ___ la lettera.','In the written story, the doctor read the letter.','lesse',['lesse','legge','leggerà'],'Lesse is the literary completed-past form.','Choose the written narrative event.'],['Nel racconto orale: «Il medico ___ la lettera».','In the conversational account: “The doctor read the letter.”','ha letto',null,'Ha letto retells the same event conversationally.','Keep the completed event but change register.'],['Nel 1905 il medico aprì la porta e ___ il documento.','In 1905 the doctor opened the door and found the document.','trovò',['trovò','trova','troverà'],'Trovò follows aprì in the written sequence.','Match the written narrative register.'],['Nel racconto orale: «Nel 1905 il medico ___ la porta».','In the conversational account: “In 1905 the doctor opened the door.”','ha aperto',null,'Ha aperto preserves the event in conversational register.','Use passato prossimo.']],application:['Retell a written scene','Read the short story, then tell a friend in conversational Italian the two main events and their order.','Nel 1905 il medico ha aperto l’archivio. Ha trovato una lettera importante e l’ha portata al direttore.',['The retelling preserves people, events and order.','Conversational forms are used consistently.','No new event is added.'],'speak'],passage:{title:'The archive',it:'Nel 1905 il medico aprì l’archivio. Trovò una lettera importante e la portò al direttore.',en:'In 1905 the doctor opened the archive. He found an important letter and took it to the director.',mode:'read',task:'Retell the event sequence without copying the literary forms.'}});

// B2.12: select, listen for and relay the information an audience actually needs.
fresh('B2',{
 id:'v2-b2-audience-needs',title:'Select relevant details',outcome:'I can select source details for a person with a stated practical need.',takeaway:'A good relay includes information the audience can act on and marks missing information as missing.',prerequisites:['v2-b2-report-versus-story'],modality:'reading',passageBeforeGuided:true,
 words:[['la prenotazione','reservation'],['l’accesso','access'],['accessibile','accessible'],['la scadenza','deadline']],
 models:[['Start with the audience’s question','For a visitor using a wheelchair, access information matters more than exhibition history.','Per chi usa una sedia a rotelle, l’ingresso accessibile è sul lato nord.','For someone using a wheelchair, the accessible entrance is on the north side.'],['Do not invent an unstated detail','If the notice does not give a lift opening time, say that it does not specify one.','L’avviso non specifica l’orario dell’ascensore.','The notice does not specify the lift’s hours.']],
 checks:[['Secondo l’avviso, l’ingresso accessibile è sul lato ___.','','nord',['nord','sud','ovest'],'The notice locates accessible entry on the north side.','Find the entrance location.'],['La prenotazione va fatta entro ___.','','giovedì',null,'Thursday is the booking deadline.','Locate the deadline, not the visit day.'],['L’avviso ___ l’orario dell’ascensore.','','non specifica',['non specifica','conferma','garantisce'],'The lift hours are absent from the source.','Mark what is unknown.'],['Il laboratorio è rivolto ai ragazzi dai ___ anni.','','dodici',null,'The age threshold is twelve.','Preserve the exact age.']],
 application:['Brief a visitor','Write a concise message for a visitor who uses a wheelchair and is bringing a 12-year-old child. Include access, booking and one unknown to check.','L’ingresso accessibile è sul lato nord. Il laboratorio accetta ragazzi dai dodici anni, quindi vostro figlio può partecipare. Bisogna prenotare entro giovedì. L’avviso non specifica l’orario dell’ascensore: vi consiglio di chiedere al museo prima della visita.',['The chosen facts match the visitor’s needs.','The age and deadline are accurate.','The unknown is marked as unknown, with a practical next step.'],'mediate'],
 passage:{title:'Visitor information',it:'Museo del Porto — Sabato la mostra apre alle dieci. L’ingresso principale è su Piazza Grande; l’ingresso accessibile è sul lato nord, vicino alla fermata dell’autobus. Il laboratorio per ragazzi accetta partecipanti dai dodici anni e dura un’ora. I posti sono limitati: bisogna prenotare entro giovedì tramite il sito del museo. I biglietti si ritirano all’ingresso scelto. L’avviso non specifica l’orario dell’ascensore né il costo del laboratorio. Per informazioni si può telefonare alla segreteria dal lunedì al venerdì.',en:'Harbour Museum — On Saturday the exhibition opens at ten. The main entrance is on Piazza Grande; the accessible entrance is on the north side, near the bus stop. The workshop accepts children aged twelve and over and lasts one hour. Places are limited: book by Thursday through the museum website. Tickets are collected at the chosen entrance. The notice does not specify the lift’s hours or the workshop price. For information, call the office Monday to Friday.',mode:'read',task:'Select details relevant to an accessible family visit.'}
});
